fn representation_candidate(
    function: &ResolvedFunction,
    cfg_paths: usize,
    semantic_paths: usize,
) -> bool {
    if cfg_paths <= FACTORED_PATH_THRESHOLD && semantic_paths <= FACTORED_PATH_THRESHOLD {
        return false;
